PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?p ?cls ?s WHERE {
  ?p a brick:ElectricPowerSensor ;
     brick:hasPropertyType brick:ElectricPower ;
     brick:hasLocation ?loc .
  ?loc a brick:LightingControl .
  ?p ref:hasTimeseriesId ?s .
} LIMIT 50

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?p ?s WHERE {
  ?p a brick:ElectricPowerSensor .
  ?p brick:hasLocation ?loc .
  ?loc a brick:Building .
  OPTIONAL { ?p ref:hasTimeseriesId ?s }
} LIMIT 50

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?p ?cls ?loc WHERE {
  ?p a ?cls .
  FILTER (str(?cls) LCONTAINS "Sensor")
  ?p brick:hasLocation ?loc .
} LIMIT 80

SELECT ?p ?cls WHERE {
  ?p a ?cls .
  FILTER (str(?cls) LCONTAINS "Power")
} LIMIT 80

SELECT ?p (STR(?cls) AS cls) WHERE {
  ?p a ?cls .
} LIMIT 200

